 <section class="cpcc-commercial-trace" aria-label="Commercial trace"><h2><?php echo cpcc_ui_english_label('Order Journey', 'مسار الطلب / Order Journey'); ?></h2><div class="cpcc-trace-grid"><article><span><?php echo cpcc_ui_english_label('Project', 'المشروع / Project'); ?></span><?php if($project){$url=cpcc_portal_scoped_url('/chinaplanetcustomercenter/project.php',$isExternal,$socid,array('id'=>(int)$project->rowid));?><a href="<?php echo dol_escape_htmltag($url); ?>"><?php echo dol_escape_htmltag($project->ref); ?></a><?php }else{ ?><strong><?php echo cpcc_ui_english_label('Not linked', 'غير مرتبط / Not linked'); ?></strong><?php } ?></article><article><span><?php echo cpcc_ui_english_label('Quotation', 'عرض السعر / Quotation'); ?></span><strong><?php echo dol_escape_htmltag($proposal->ref); ?></strong></article><article><span><?php echo cpcc_ui_english_label('Sales Order', 'طلب البيع / Sales Order'); ?></span><?php if($orders){foreach($orders as $order){$url=cpcc_portal_scoped_url('/chinaplanetcustomercenter/order.php',$isExternal,$socid,array('id'=>(int)$order->rowid));?><a href="<?php echo dol_escape_htmltag($url); ?>"><?php echo dol_escape_htmltag($order->ref); ?></a><?php }}else{ ?><strong><?php echo cpcc_ui_english_label('Pending', 'بانتظار إنشاء الطلب / Pending'); ?></strong><?php } ?></article></div></section>
